import {getAIInput} from './app.js';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const controls=document.createElement('section');controls.className='panel ai-controls';controls.id='ai-controls';
controls.innerHTML=`<div class="panel-title"><span class="step">✦</span><div><h3>Let AI take a closer look</h3><p>Review a photo, PDF, notes, or the medicines entered below.</p></div></div><p class="micro">AI looks for possible unusual doses, medicine combinations, repeated ingredients and unclear instructions. It can make mistakes. If details are unclear or the review fails, we ask for a pharmacist's opinion.</p><div id="ai-connection" class="micro" role="status">Checking AI availability…</div><label class="confirm"><input type="checkbox" id="ai-consent"> I agree to send this prescription and the health details entered here through ScriptCheck's server to OpenAI for AI review. I have permission to share them.</label><p class="micro">Remove names and personal identifiers first. OpenAI may retain request data for abuse monitoring. AI review is optional; local rule checks stay on this device. AI files: maximum 3 MB.</p><button id="ai-analyze" class="button primary analyze">Review prescription with AI <span>✦</span></button><p id="ai-message" class="micro" role="alert"></p>`;
document.querySelector('.intake').after(controls);
const panel=document.createElement('section');panel.id='ai-result';panel.className='results-panel ai-result';panel.setAttribute('aria-live','polite');panel.hidden=true;$('results').before(panel);
let revision=0,controller=null,current=null;
function reset(){revision++;controller?.abort();controller=null;current=null;$('ai-analyze').disabled=false;if(!panel.hidden){panel.innerHTML='<div class="eyebrow">AI REVIEW NEEDS UPDATING</div><p>The details changed. Run AI review again. The previous result is no longer current.</p>';}}
$('checker').addEventListener('input',e=>{if(!controls.contains(e.target))reset();});
$('checker').addEventListener('click',e=>{if(e.target.closest('#add,[data-remove],#clear')){reset();if(e.target.closest('#clear')){$('ai-consent').checked=false;panel.hidden=true;}}});
$('demo').addEventListener('click',reset);
$('ai-consent').addEventListener('change',()=>{if(!$('ai-consent').checked)reset();});
document.addEventListener('prescription-changed',reset);
const asDataUrl=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read this file.'));reader.readAsDataURL(file);});
function fallback(reason){return{status:'pharmacist_required',aiCompleted:false,summary:'We could not complete the AI review. Please ask a pharmacist to check this prescription.',reasons:[reason],pharmacistQuestions:['Are the medicine names, strengths and instructions correct?','Could any of these medicines cause problems together?'],reviewRequired:true};}
function render(r){const title=r.status==='pharmacist_required'?'A pharmacist needs to take a look':r.status==='potential_concerns'?'AI found possible concerns':'AI did not identify a concern';
 panel.hidden=false;panel.innerHTML=`<div class="eyebrow">${r.aiCompleted?'AI PRELIMINARY REVIEW':'AI REVIEW INCOMPLETE'}</div><h3>${title}</h3><p>${esc(r.summary)}</p><div class="stale"><strong>${r.status==='pharmacist_required'?'Please ask for a pharmacist’s opinion.':'Have a pharmacist verify this review.'}</strong><br>AI can miss serious problems. Do not change your medicines based on this result.</div>${r.reasons?.length?`<div class="coverage"><strong>Why a professional should check</strong><ul>${r.reasons.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${(r.findings||[]).map(f=>`<article class="finding ${f.urgency==='prompt_review'?'priority':''}"><span class="severity">${f.urgency==='prompt_review'?'Prompt pharmacist review':'Discuss with your pharmacist'} · AI hypothesis</span><h4>${esc(f.title)}</h4><p class="trigger">${f.affected_medicines.map(esc).join(' + ')}</p><p>${esc(f.explanation)}</p><p class="action">Ask: ${esc(f.question_for_pharmacist)}</p></article>`).join('')}${r.rules?.findings?.length?`<div class="coverage"><strong>Independent rule warnings — still apply</strong>${r.rules.findings.map(f=>`<article class="finding ${f.level}"><h4>${esc(f.title)}</h4><p>${esc(f.trigger)}</p><p>${esc(f.explanation)}</p></article>`).join('')}</div>`:''}${r.medicinesRead?.length?`<details class="coverage"><summary>What the AI read — unverified</summary><ul>${r.medicinesRead.map(m=>`<li>${esc(m.name)} · ${esc(m.strength)} · ${esc(m.schedule)}${m.unclear?' — unclear':''}</li>`).join('')}</ul></details>`:''}<div class="coverage"><strong>Questions to take to your pharmacist</strong><ul>${(r.pharmacistQuestions||[]).map(q=>`<li>${esc(q)}</li>`).join('')}</ul></div><p class="micro">${r.aiCompleted?`Model: ${esc(r.model)} · Prompt: ${esc(r.promptVersion)}<br>`:''}This is not a diagnosis, a complete safety check, or a pharmacist's opinion. No pharmacist has been contacted.</p><div class="report-actions"><button class="secondary" id="ai-download">Download pharmacist handoff ↓</button></div>`;
 $('ai-download').onclick=()=>{if(!current)return;const text=['ScriptCheck — preliminary AI review','For pharmacist review; not treatment instructions.',r.aiCompleted?`Model: ${r.model}; prompt: ${r.promptVersion}`:'AI review incomplete',r.summary,'',...(r.reasons||[]),'',...(r.findings||[]).flatMap(f=>[f.title,f.affected_medicines.join(' + '),f.explanation,f.question_for_pharmacist,'']),'Independent rules:',...(r.rules?.findings||[]).flatMap(f=>[f.title,f.trigger,f.explanation,f.source||'']),'Draft medicine reading:',...(r.medicinesRead||[]).map(m=>`${m.name}: ${m.strength}; ${m.schedule}; unclear: ${m.unclear}`),'Questions:',...(r.pharmacistQuestions||[]),'No pharmacist has been contacted. Bring the original prescription and your medicine packets.'].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='scriptcheck-pharmacist-review.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
}
async function checkConnection(){try{const res=await fetch('/.netlify/functions/ai-review',{cache:'no-store'});if(!res.ok)throw new Error();const data=await res.json();$('ai-connection').textContent=data.configured?`AI service connected · ${data.model}. Results still need professional review.`:'AI setup pending. A pharmacist-review handoff is available; the owner must connect the AI service.';}catch{$('ai-connection').textContent='AI service unavailable here. Use the local checks and ask a pharmacist.';}}
$('ai-analyze').onclick=async()=>{
 if(!$('ai-consent').checked){$('ai-message').textContent='Please read and accept the data-sharing notice before requesting AI review.';return;}
 const input=getAIInput();if(!input.file&&!input.text.trim()&&!input.medicines.some(m=>m.name.trim())){$('ai-message').textContent='Upload a prescription, paste its text, or enter a medicine first.';return;}
 if(input.file&&input.file.type!=='text/plain'&&input.file.size>3*1024*1024){$('ai-message').textContent='For AI review, choose a file smaller than 3 MB, or enter the prescription as text.';return;}
 controller?.abort();const run=++revision;const activeController=new AbortController();controller=activeController;current=null;$('ai-analyze').disabled=true;$('ai-message').textContent='Reading the prescription and checking for possible concerns…';panel.hidden=false;panel.innerHTML='<div class="eyebrow">AI REVIEW IN PROGRESS</div><p>Checking the details you provided. This usually takes several seconds.</p>';const timeout=setTimeout(()=>activeController.abort(),55000);
 try{
  let document=null;if(input.file&&input.file.type!=='text/plain')document={type:input.file.type,data:await asDataUrl(input.file)};
  if(run!==revision)return;
  const response=await fetch('/.netlify/functions/ai-review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({consent:true,text:input.text,medicines:input.medicines,context:input.context,document}),signal:activeController.signal});
  const result=response.headers.get('content-type')?.includes('application/json')?await response.json():fallback('The review service did not respond.');
  if(!response.ok&&!result.summary)throw new Error();
  if(run!==revision)return;current=result;render(result);$('ai-message').textContent=result.aiCompleted?'Preliminary review ready. Share it with your pharmacist.':'The review could not be completed. Please ask your pharmacist.';panel.scrollIntoView({behavior:'smooth',block:'start'});
 }catch{if(run===revision){current=fallback('The service is unavailable, busy, or took too long to respond.');render(current);$('ai-message').textContent='Please ask a pharmacist to review the prescription.';}}
 finally{clearTimeout(timeout);if(run===revision){controller=null;$('ai-analyze').disabled=false;}}
};
checkConnection();
